const searchWikiChunks = `-- name: SearchWikiChunks :many
SELECT c.page_id, c.chunk_index, c.chunk_text, p.title, p.slug, p.space_id,
       (c.embedding <=> $1::vector)::float8 AS distance
FROM wiki_chunks c
JOIN wiki_pages p ON p.id = c.page_id
JOIN wiki_spaces s ON s.id = c.space_id
WHERE c.tenant_id = $2 AND p.status = 'published' AND s.ai_indexed = true
  -- B9: cheap FTS pre-filter (GIN on search_tsv) before the kNN; the service retries without it on 0 results.
  AND ($3::bool = false OR p.search_tsv @@ websearch_to_tsquery('simple', $4::text))
  AND (
    s.owner_user_id = $5
    OR s.visibility IN ('org', 'public')
    OR EXISTS (
        SELECT 1 FROM wiki_space_grants g
        WHERE g.space_id = s.id AND (
            g.subject_type = 'org'
            OR (g.subject_type = 'user' AND g.subject_id = $5)
            OR (g.subject_type = 'group' AND EXISTS (
                SELECT 1 FROM user_group_members ugm
                WHERE ugm.group_id = g.subject_id AND ugm.user_id = $5))))
    OR EXISTS (
        SELECT 1 FROM wiki_page_grants g
        WHERE g.page_id = p.id AND (
            g.subject_type = 'org'
            OR (g.subject_type = 'user' AND g.subject_id = $5)
            OR (g.subject_type = 'group' AND EXISTS (
                SELECT 1 FROM user_group_members ugm
                WHERE ugm.group_id = g.subject_id AND ugm.user_id = $5))))
  )
ORDER BY c.embedding <=> $1::vector
LIMIT $6
`

type SearchWikiChunksParams struct {
	QueryEmbedding string    `json:"query_embedding"`
	TenantID       uuid.UUID `json:"tenant_id"`
	UseFts         bool      `json:"use_fts"`
	QueryText      string    `json:"query_text"`
	UserID         uuid.UUID `json:"user_id"`
	MaxResults     int32     `json:"max_results"`
}

type SearchWikiChunksRow struct {
	PageID     uuid.UUID `json:"page_id"`
	ChunkIndex int32     `json:"chunk_index"`
	ChunkText  string    `json:"chunk_text"`
	Title      string    `json:"title"`
	Slug       string    `json:"slug"`
	SpaceID    uuid.UUID `json:"space_id"`
	Distance   float64   `json:"distance"`
}

// Cosine kNN FILTERED by the asker's permission (same visibility surface, §7.4) + tenant +
// ai_indexed + published. Smaller distance = more relevant.
func (q *Queries) SearchWikiChunks(ctx context.Context, arg SearchWikiChunksParams) ([]SearchWikiChunksRow, error) {
	rows, err := q.db.Query(ctx, searchWikiChunks,
		arg.QueryEmbedding,
		arg.TenantID,
		arg.UseFts,
		arg.QueryText,
		arg.UserID,
		arg.MaxResults,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchWikiChunksRow
	for rows.Next() {
		var i SearchWikiChunksRow
		if err := rows.Scan(
			&i.PageID,
			&i.ChunkIndex,
			&i.ChunkText,
			&i.Title,
			&i.Slug,
			&i.SpaceID,
			&i.Distance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchWikiPagesText = `-- name: SearchWikiPagesText :many
SELECT p.id AS page_id, p.title, p.slug, p.space_id,
       left(p.body_text, 1200) AS snippet,
       (1.0 - ts_rank_cd(p.search_tsv, websearch_to_tsquery('simple', $1::text)))::float8 AS distance
FROM wiki_pages p
JOIN wiki_spaces s ON s.id = p.space_id
WHERE p.tenant_id = $2 AND p.status = 'published' AND s.ai_indexed = true
  AND p.search_tsv @@ websearch_to_tsquery('simple', $1::text)
  AND (
    s.owner_user_id = $3
    OR s.visibility IN ('org', 'public')
    OR EXISTS (
        SELECT 1 FROM wiki_space_grants g
        WHERE g.space_id = s.id AND (
            g.subject_type = 'org'
            OR (g.subject_type = 'user' AND g.subject_id = $3)
            OR (g.subject_type = 'group' AND EXISTS (
                SELECT 1 FROM user_group_members ugm
                WHERE ugm.group_id = g.subject_id AND ugm.user_id = $3))))
    OR EXISTS (
        SELECT 1 FROM wiki_page_grants g
        WHERE g.page_id = p.id AND (
            g.subject_type = 'org'
            OR (g.subject_type = 'user' AND g.subject_id = $3)
            OR (g.subject_type = 'group' AND EXISTS (
                SELECT 1 FROM user_group_members ugm
                WHERE ugm.group_id = g.subject_id AND ugm.user_id = $3))))
  )
ORDER BY ts_rank_cd(p.search_tsv, websearch_to_tsquery('simple', $1::text)) DESC
LIMIT $4
`

type SearchWikiPagesTextParams struct {
	QueryText  string    `json:"query_text"`
	TenantID   uuid.UUID `json:"tenant_id"`
	UserID     uuid.UUID `json:"user_id"`
	MaxResults int32     `json:"max_results"`
}

type SearchWikiPagesTextRow struct {
	PageID   uuid.UUID `json:"page_id"`
	Title    string    `json:"title"`
	Slug     string    `json:"slug"`
	SpaceID  uuid.UUID `json:"space_id"`
	Snippet  string    `json:"snippet"`
	Distance float64   `json:"distance"`
}

// LEXICAL search, straight against PAGES, with the same visibility surface as the kNN. This is
// the safety net for when there's no EMBEDDINGS_API_KEY: then no chunks exist at all (they're
// only born in embedPage), so searching the chunks would always come back empty. `search_tsv` is
// a GENERATED column -- always there, no pipeline needed. `distance` keeps the kNN's semantics
// (smaller = more relevant).
func (q *Queries) SearchWikiPagesText(ctx context.Context, arg SearchWikiPagesTextParams) ([]SearchWikiPagesTextRow, error) {
	rows, err := q.db.Query(ctx, searchWikiPagesText,
		arg.QueryText,
		arg.TenantID,
		arg.UserID,
		arg.MaxResults,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchWikiPagesTextRow
	for rows.Next() {
		var i SearchWikiPagesTextRow
		if err := rows.Scan(
			&i.PageID,
			&i.Title,
			&i.Slug,
			&i.SpaceID,
			&i.Snippet,
			&i.Distance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

