const wikiPageRole = `-- name: WikiPageRole :one
SELECT COALESCE(MAX(rank), 0)::int AS role_rank FROM (
    SELECT CASE WHEN s.owner_user_id = $1 THEN 4
                WHEN s.visibility IN ('org', 'public') THEN 1 ELSE 0 END AS rank
    FROM wiki_pages p JOIN wiki_spaces s ON s.id = p.space_id
    WHERE p.id = $2 AND p.tenant_id = $3
    UNION ALL
    SELECT CASE g.role WHEN 'manager' THEN 4 WHEN 'editor' THEN 3 WHEN 'commenter' THEN 2 ELSE 1 END
    FROM wiki_pages p JOIN wiki_space_grants g ON g.space_id = p.space_id
    WHERE p.id = $2 AND p.tenant_id = $3 AND (
        g.subject_type = 'org'
        OR (g.subject_type = 'user' AND g.subject_id = $1)
        OR (g.subject_type = 'group' AND EXISTS (
            SELECT 1 FROM user_group_members ugm
            WHERE ugm.group_id = g.subject_id AND ugm.user_id = $1))
    )
    UNION ALL
    SELECT CASE g.role WHEN 'manager' THEN 4 WHEN 'editor' THEN 3 WHEN 'commenter' THEN 2 ELSE 1 END
    FROM wiki_page_grants g
    WHERE g.page_id = $2 AND g.tenant_id = $3 AND (
        g.subject_type = 'org'
        OR (g.subject_type = 'user' AND g.subject_id = $1)
        OR (g.subject_type = 'group' AND EXISTS (
            SELECT 1 FROM user_group_members ugm
            WHERE ugm.group_id = g.subject_id AND ugm.user_id = $1))
    )
) t
`

type WikiPageRoleParams struct {
	UserID   uuid.UUID `json:"user_id"`
	PageID   uuid.UUID `json:"page_id"`
	TenantID uuid.UUID `json:"tenant_id"`
}

// Effective role (rank) of the user on a page = max(role inherited from the space, page grants).
func (q *Queries) WikiPageRole(ctx context.Context, arg WikiPageRoleParams) (int32, error) {
	row := q.db.QueryRow(ctx, wikiPageRole, arg.UserID, arg.PageID, arg.TenantID)
	var role_rank int32
	err := row.Scan(&role_rank)
	return role_rank, err
}

